Source code in <code>cntrl/patch_switcher/data_files.py</code> <pre><code>def expressions(
    arguments: list[str], errors: list[str] | None = None
) -&gt; list[DataFile]:
    groups: list[list[str]] = []
    own_errors = errors is None
    if errors is None:
        errors = []
    joining = False
    for a in arguments:
        if a == '+':
            if not groups or joining:
                errors.append('unexpected +: expected a data file')
            joining = True
        else:
            if joining and groups:
                groups[-1].append(a)
            else:
                groups.append([a])
            joining = False
    if joining:
        errors.append('trailing +: expected a data file')
    result: list[DataFile] = []
    for g in groups:
        name: str | None = None
        paths: list[Path] = []
        for i, a in enumerate(g):
            prefix = ''
            j = 0
            while j &lt; len(a):
                if a[j : j + 2] in ('==', '\\='):
                    prefix += '='
                    j += 2
                elif a[j] == '=':
                    break
                else:
                    prefix += a[j]
                    j += 1
            if j &lt; len(a):
                if i:
                    errors.append(
                        f'{a}: a name is allowed only before the first operand'
                    )
                else:
                    name = prefix
                a = a[j + 1 :]
            if not a:
                errors.append('empty data-file path')
            paths.append(Path(a))
        result.append(
            DataFile(
                name=name if name is not None else '+'.join(p.stem for p in paths),
                paths=paths,
            )
        )
    if errors and own_errors:
        raise CompilationError(errors)
    return result
