Source code in <code>cntrl/patch_switcher/transport.py</code> <pre><code>def write_frame(self, data: bytes) -&gt; None:
    deadline = time.monotonic() + self.timeout
    pending = memoryview(data)
    while pending:
        remaining = deadline - time.monotonic()
        if remaining &lt;= 0 or not select.select([], [self.fd], [], remaining)[1]:
            raise TimeoutError('USB serial write timed out')
        try:
            count = os.write(self.fd, pending)
        except BlockingIOError:
